import hashlib
import re
from typing import Any

from phs.baiying.rules import INTENT_TO_TRIGGER, MAX_COMMENT_LENGTH


def _fingerprint(user: str, text: str) -> str:
    raw = f"{user.strip()}::{text.strip()}".encode("utf-8")
    return hashlib.sha256(raw).hexdigest()


def _hash_user(user: str) -> str:
    return hashlib.sha256(user.strip().encode("utf-8")).hexdigest()[:16]


def classify_intent(text: str) -> str:
    normalized = text.lower()

    if any(k in normalized for k in ("多少钱", "价格", "几块", "多少米", "price")):
        return "price"

    if any(k in normalized for k in ("优惠", "券", "满减", "coupon")):
        return "coupon"

    if any(k in normalized for k in ("发货", "包邮", "快递", "shipping")):
        return "shipping"

    if any(k in normalized for k in ("材质", "材料", "什么做的", "material")):
        return "material"

    if any(k in normalized for k in ("尺寸", "多大", "规格", "size")):
        return "size"

    if any(k in normalized for k in ("还有吗", "库存", "有货", "stock")):
        return "stock"

    return "general"


async def process_comment(bridge: Any, comment: dict[str, Any]) -> dict[str, Any] | None:
    """
    从原 BaiyingBridge.process_comment 原样迁移。

    迁移要求：
    1. 不改原逻辑。
    2. 原来的 self 改为 bridge。
    3. 原 self.xxx 全部改成 bridge.xxx。
    4. 原 return 保持不变。
    """

    raw_text = str(comment.get("text", "")).strip()
    raw_user = str(comment.get("user", "")).strip() or "anonymous"

    if not raw_text:
        return None

    if len(raw_text) > MAX_COMMENT_LENGTH:
        raw_text = raw_text[:MAX_COMMENT_LENGTH]

    fingerprint = _fingerprint(raw_user, raw_text)

    if hasattr(bridge, "event_store") and bridge.event_store:
        if bridge.event_store.exists_fingerprint(fingerprint):
            return {
                "ok": False,
                "reason": "duplicate",
                "fingerprint": fingerprint,
            }

    intent = classify_intent(raw_text)
    trigger = INTENT_TO_TRIGGER.get(intent, "general")

    if hasattr(bridge, "sensitive_guard") and bridge.sensitive_guard:
        sensitive_result = bridge.sensitive_guard.check(raw_text)
        if not sensitive_result.ok:
            if hasattr(bridge, "event_store") and bridge.event_store:
                bridge.event_store.save_comment_event(
                    {
                        "user_hash": _hash_user(raw_user),
                        "text": raw_text,
                        "intent": intent,
                        "fingerprint": fingerprint,
                        "blocked": True,
                        "block_reason": sensitive_result.reason,
                    }
                )
            return {
                "ok": False,
                "reason": "sensitive_comment",
                "detail": sensitive_result.reason,
            }

    product = None
    if hasattr(bridge, "_get_current_product_for_pipeline"):
        product = bridge._get_current_product_for_pipeline()

    template_vars = bridge._build_template_variables(
        comment=comment,
        product=product,
        intent=intent,
    )

    script = None
    if hasattr(bridge, "script_manager") and bridge.script_manager:
        script = bridge.script_manager.match(
            text=raw_text,
            intent=intent,
            trigger=trigger,
            product=product,
        )

    if script is None:
        return {
            "ok": False,
            "reason": "no_script_matched",
            "intent": intent,
        }

    reply = script.render(template_vars)

    reply = re.sub(r"\s+", " ", reply).strip()

    if hasattr(bridge, "sensitive_guard") and bridge.sensitive_guard:
        reply_check = bridge.sensitive_guard.check(reply)
        if not reply_check.ok:
            if hasattr(bridge, "event_store") and bridge.event_store:
                bridge.event_store.save_comment_event(
                    {
                        "user_hash": _hash_user(raw_user),
                        "text": raw_text,
                        "reply": reply,
                        "intent": intent,
                        "fingerprint": fingerprint,
                        "blocked": True,
                        "block_reason": reply_check.reason,
                    }
                )
            return {
                "ok": False,
                "reason": "sensitive_reply",
                "detail": reply_check.reason,
            }

    audit_required = bool(getattr(bridge, "manual_audit_enabled", False))

    event_payload = {
        "user_hash": _hash_user(raw_user),
        "text": raw_text,
        "reply": reply,
        "intent": intent,
        "fingerprint": fingerprint,
        "product": product,
        "audit_required": audit_required,
    }

    if hasattr(bridge, "event_store") and bridge.event_store:
        bridge.event_store.save_comment_event(event_payload)

    if audit_required:
        return {
            "ok": True,
            "status": "pending_manual_audit",
            "reply": reply,
            "intent": intent,
            "fingerprint": fingerprint,
        }

    if hasattr(bridge, "tts_queue") and bridge.tts_queue:
        bridge.tts_queue.enqueue(
            text=reply,
            metadata={
                "intent": intent,
                "fingerprint": fingerprint,
                "user_hash": _hash_user(raw_user),
            },
        )

    return {
        "ok": True,
        "status": "queued",
        "reply": reply,
        "intent": intent,
        "fingerprint": fingerprint,
    }
