import asyncio
from typing import Any

from phs.baiying.rules import BYY_ENTRY_URL, LIVE_CONTROL_KEYWORDS


async def _launch_browser(bridge: Any) -> None:
    """
    从原 BaiyingBridge._launch_browser 原样迁移。
    """

    if bridge.playwright is not None and bridge.browser_context is not None:
        return

    from playwright.async_api import async_playwright

    bridge.playwright = await async_playwright().start()

    bridge.browser_context = await bridge.playwright.chromium.launch_persistent_context(
        user_data_dir=str(bridge.profile_dir),
        headless=False,
        args=[
            "--disable-blink-features=AutomationControlled",
            "--disable-dev-shm-usage",
            "--no-first-run",
            "--no-default-browser-check",
        ],
    )

    if bridge.browser_context.pages:
        bridge.page = bridge.browser_context.pages[0]
    else:
        bridge.page = await bridge.browser_context.new_page()

    await bridge.page.goto(BYY_ENTRY_URL, wait_until="domcontentloaded")
    await _wait_for_login_and_stable(bridge)


async def _close_browser(bridge: Any) -> None:
    if getattr(bridge, "browser_context", None) is not None:
        await bridge.browser_context.close()
        bridge.browser_context = None

    if getattr(bridge, "playwright", None) is not None:
        await bridge.playwright.stop()
        bridge.playwright = None

    bridge.page = None


async def _is_on_live_control(bridge: Any) -> bool:
    page = getattr(bridge, "page", None)
    if page is None:
        return False

    try:
        url = page.url or ""
        title = await page.title()

        haystack = f"{url} {title}".lower()

        return any(keyword.lower() in haystack for keyword in LIVE_CONTROL_KEYWORDS)

    except Exception:
        return False


async def _wait_for_login_and_stable(bridge: Any) -> None:
    page = getattr(bridge, "page", None)
    if page is None:
        raise RuntimeError("Browser page is not initialized")

    deadline = getattr(bridge, "login_timeout_seconds", 1800)
    interval = 3

    elapsed = 0

    while elapsed < deadline:
        if await _is_on_live_control(bridge):
            await asyncio.sleep(2)
            return

        await asyncio.sleep(interval)
        elapsed += interval

    raise TimeoutError("Waiting for Baiying login/live control page timed out")
