import asyncio
from typing import Any

from phs.baiying.rules import DANMAKU_SELECTOR_CANDIDATES


async def _install_dom_observer(bridge: Any) -> None:
    page = getattr(bridge, "page", None)
    if page is None:
        raise RuntimeError("Browser page is not initialized")

    selector_list = list(DANMAKU_SELECTOR_CANDIDATES)

    await page.expose_function(
        "__phs_push_comment",
        lambda payload: bridge.comment_queue.put_nowait(payload),
    )

    await page.evaluate(
        """
        (selectors) => {
            if (window.__phs_dom_observer_installed) return;
            window.__phs_dom_observer_installed = true;

            const seen = new Set();

            function textOf(node) {
                if (!node) return "";
                return (node.innerText || node.textContent || "").trim();
            }

            function pushNode(node) {
                const text = textOf(node);
                if (!text) return;
                if (seen.has(text)) return;
                seen.add(text);

                window.__phs_push_comment({
                    text,
                    user: "",
                    ts: Date.now(),
                    source: "dom"
                });
            }

            const observer = new MutationObserver((mutations) => {
                for (const mutation of mutations) {
                    for (const node of mutation.addedNodes) {
                        if (!node || node.nodeType !== 1) continue;

                        for (const selector of selectors) {
                            if (node.matches && node.matches(selector)) {
                                pushNode(node);
                            }

                            if (node.querySelectorAll) {
                                node.querySelectorAll(selector).forEach(pushNode);
                            }
                        }
                    }
                }
            });

            observer.observe(document.body, {
                childList: true,
                subtree: true
            });
        }
        """,
        selector_list,
    )


async def _collection_loop(bridge: Any) -> None:
    while getattr(bridge, "running", False):
        try:
            await _drain_and_process(bridge)
        except Exception as exc:
            if hasattr(bridge, "logger"):
                bridge.logger.exception("Baiying collection loop error: %s", exc)

        await asyncio.sleep(getattr(bridge, "collection_interval_seconds", 1))


async def _drain_and_process(bridge: Any) -> None:
    batch_size = getattr(bridge, "collection_batch_size", 30)
    comments: list[dict[str, Any]] = []

    for _ in range(batch_size):
        try:
            comment = bridge.comment_queue.get_nowait()
            comments.append(comment)
        except asyncio.QueueEmpty:
            break

    if not comments:
        return

    for comment in comments:
        await bridge.process_comment(comment)
