        bridge.logger.info("Current product changed: %s", product)


def _get_current_product_for_status(bridge: Any) -> dict[str, Any] | None:
    product = getattr(bridge, "current_product", None)

    if product is None:
        return None

    if isinstance(product, dict):
        return product

    if hasattr(product, "model_dump"):
        return product.model_dump()

    if hasattr(product, "dict"):
        return product.dict()

    return {
        "value": str(product),
    }


def _get_current_product_for_pipeline(bridge: Any) -> Any:
    return getattr(bridge, "current_product", None)
