import asyncio
import logging
from pathlib import Path
from typing import Any

from phs.baiying.browser import (
    _close_browser as browser_close_browser,
)
from phs.baiying.browser import (
    _is_on_live_control as browser_is_on_live_control,
)
from phs.baiying.browser import (
    _launch_browser as browser_launch_browser,
)
from phs.baiying.browser import (
    _wait_for_login_and_stable as browser_wait_for_login_and_stable,
)
from phs.baiying.collector import (
    _collection_loop as collector_collection_loop,
)
from phs.baiying.collector import (
    _drain_and_process as collector_drain_and_process,
)
from phs.baiying.collector import (
    _install_dom_observer as collector_install_dom_observer,
)
from phs.baiying.pipeline import classify_intent
from phs.baiying.pipeline import process_comment as pipeline_process_comment
from phs.baiying.product import (
    _get_current_product_for_pipeline as product_get_current_product_for_pipeline,
)
from phs.baiying.product import (
    _get_current_product_for_status as product_get_current_product_for_status,
)
from phs.baiying.product import (
    _on_product_change as product_on_product_change,
)
from phs.baiying.rules import DEFAULT_PROFILE_DIR


class BaiyingBridge:
    classify_intent = staticmethod(classify_intent)

    def __init__(
        self,
        profile_dir: str | Path | None = None,
        manual_audit_enabled: bool = False,
        login_timeout_seconds: int = 1800,
        collection_interval_seconds: float = 1.0,
        collection_batch_size: int = 30,
        logger: logging.Logger | None = None,
        **kwargs: Any,
    ) -> None:
        self.profile_dir = Path(profile_dir or DEFAULT_PROFILE_DIR)
        self.profile_dir.mkdir(parents=True, exist_ok=True)

        self.manual_audit_enabled = manual_audit_enabled
        self.login_timeout_seconds = login_timeout_seconds
        self.collection_interval_seconds = collection_interval_seconds
        self.collection_batch_size = collection_batch_size

        self.logger = logger or logging.getLogger(__name__)

        self.running = False
        self.started = False

        self.playwright = None
        self.browser_context = None
        self.page = None

        self.comment_queue: asyncio.Queue[dict[str, Any]] = asyncio.Queue()
        self.collection_task: asyncio.Task[Any] | None = None

        self.current_product: Any = None

        self.script_manager = kwargs.get("script_manager")
        self.product_collector = kwargs.get("product_collector")
        self.tts_queue = kwargs.get("tts_queue")
        self.sensitive_guard = kwargs.get("sensitive_guard")
        self.event_store = kwargs.get("event_store")

        self.extra = kwargs

    async def start(self) -> None:
        if self.running:
            return

        await self._init_modules()
        await self._launch_browser()
        await self._install_dom_observer()

        self.running = True
        self.started = True

        self.collection_task = asyncio.create_task(self._collection_loop())

    async def stop(self) -> None:
        self.running = False

        if self.collection_task is not None:
            self.collection_task.cancel()
            try:
                await self.collection_task
            except asyncio.CancelledError:
                pass
            self.collection_task = None

        await self._close_browser()
        await self._close_modules()

        self.started = False

    async def get_status(self) -> dict[str, Any]:
        return {
            "running": self.running,
            "started": self.started,
            "profile_dir": str(self.profile_dir),
            "browser_open": self.browser_context is not None,
            "page_open": self.page is not None,
            "on_live_control": await self._is_on_live_control(),
            "queue_size": self.comment_queue.qsize(),
            "current_product": self._get_current_product_for_status(),
            "manual_audit_enabled": self.manual_audit_enabled,
            "modules": {
                "script_manager": self.script_manager is not None,
                "product_collector": self.product_collector is not None,
                "tts_queue": self.tts_queue is not None,
                "sensitive_guard": self.sensitive_guard is not None,
                "event_store": self.event_store is not None,
            },
        }

    async def process_comment(self, comment: dict[str, Any]) -> dict[str, Any] | None:
        return await pipeline_process_comment(self, comment)

    async def manual_approve_reply(self, fingerprint: str) -> dict[str, Any]:
        if self.event_store is None:
            raise RuntimeError("event_store is not initialized")

        event = self.event_store.get_by_fingerprint(fingerprint)

        if event is None:
            return {
                "ok": False,
                "reason": "event_not_found",
                "fingerprint": fingerprint,
            }

        reply = event.get("reply")

        if not reply:
            return {
                "ok": False,
                "reason": "reply_not_found",
                "fingerprint": fingerprint,
            }

        if self.tts_queue is not None:
            self.tts_queue.enqueue(
                text=reply,
                metadata={
                    "fingerprint": fingerprint,
                    "manual_approved": True,
                },
            )

        self.event_store.mark_manual_approved(fingerprint)

        return {
            "ok": True,
            "status": "approved",
            "fingerprint": fingerprint,
        }

    async def manual_reject_reply(self, fingerprint: str, reason: str | None = None) -> dict[str, Any]:
        if self.event_store is None:
            raise RuntimeError("event_store is not initialized")

        event = self.event_store.get_by_fingerprint(fingerprint)

        if event is None:
            return {
                "ok": False,
                "reason": "event_not_found",
                "fingerprint": fingerprint,
            }

        self.event_store.mark_manual_rejected(
            fingerprint=fingerprint,
            reason=reason,
        )

        return {
            "ok": True,
            "status": "rejected",
            "fingerprint": fingerprint,
            "reason": reason,
        }

    async def _init_modules(self) -> None:
        if self.script_manager and hasattr(self.script_manager, "start"):
            result = self.script_manager.start()
            if asyncio.iscoroutine(result):
                await result

        if self.product_collector and hasattr(self.product_collector, "start"):
            result = self.product_collector.start(on_change=self._on_product_change)
            if asyncio.iscoroutine(result):
                await result

        if self.tts_queue and hasattr(self.tts_queue, "start"):
            result = self.tts_queue.start()
            if asyncio.iscoroutine(result):
                await result

        if self.event_store and hasattr(self.event_store, "start"):
            result = self.event_store.start()
            if asyncio.iscoroutine(result):
                await result

    async def _close_modules(self) -> None:
        for module in (
            self.product_collector,
            self.tts_queue,
            self.script_manager,
            self.event_store,
        ):
            if module and hasattr(module, "stop"):
                result = module.stop()
                if asyncio.iscoroutine(result):
                    await result

    def _build_template_variables(
        self,
        comment: dict[str, Any],
        product: Any,
        intent: str,
    ) -> dict[str, Any]:
        return {
            "comment": comment,
            "comment_text": comment.get("text", ""),
            "user": comment.get("user", ""),
            "product": product,
            "intent": intent,
        }

    async def _launch_browser(self) -> None:
        await browser_launch_browser(self)

    async def _close_browser(self) -> None:
        await browser_close_browser(self)

    async def _is_on_live_control(self) -> bool:
        return await browser_is_on_live_control(self)

    async def _wait_for_login_and_stable(self) -> None:
        await browser_wait_for_login_and_stable(self)

    async def _install_dom_observer(self) -> None:
        await collector_install_dom_observer(self)

    async def _collection_loop(self) -> None:
        await collector_collection_loop(self)

    async def _drain_and_process(self) -> None:
        await collector_drain_and_process(self)

    def _on_product_change(self, product: dict[str, Any] | None) -> None:
        product_on_product_change(self, product)

    def _get_current_product_for_status(self) -> dict[str, Any] | None:
        return product_get_current_product_for_status(self)

    def _get_current_product_for_pipeline(self) -> Any:
        return product_get_current_product_for_pipeline(self)

